def add_points(scores, name, points):
    if name in scores:
        scores[name] = scores[name] + points
    else:
        scores[name] = points

def top_player(scores):
    if not scores:
        return "nobody"
    best = None
    for name in scores:
        if best is None or scores[name] > scores[best]:
            best = name
    return name_points(best, scores)

def name_points(n, scores):
    return n + ": " + str(scores[n])
